import { useState } from "react";
import { useNavigate } from "react-router-dom";
import ForgotPasswordPopup from "./ForgotPasswordPopup";

const API = "http://localhost:5000/api/auth";

const inputStyle = (focus) => ({
  width: "100%",
  height: "48px",
  padding: "0 14px",
  border: `1.5px solid ${focus ? "rgb(148, 0, 211)" : "#e0c8f8"}`,
  borderRadius: "8px",
  outline: "none",
  background: focus ? "#f5eaff" : "#fdf8ff",
  marginBottom: "14px",
  fontSize: "14px",
  fontFamily: "inherit",
  boxSizing: "border-box",
});

// ─── OTP Popup Modal ─────────────────────────────────────────────────────────
function OtpLoginPopup({ onClose, onSuccess }) {
  const [step, setStep] = useState("enter_email"); // "enter_email" | "enter_otp"
  const [identifier, setIdentifier] = useState("");
  const [otp, setOtp] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [focusId, setFocusId] = useState(false);
  const [focusOtp, setFocusOtp] = useState(false);

  // Step 1: Send OTP (only for registered emails/phones)
  const handleSendOtp = async () => {
    setError("");
    if (!identifier.trim()) {
      setError("Email ya Phone number daalna zaroori hai.");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch(`${API}/send-login-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ identifier: identifier.trim() }),
      });
      const data = await res.json();

      if (data.success) {
        setStep("enter_otp");
        setError("");
      } else {
        // Backend should return specific message if user not registered
        setError(data.message || "OTP bhejne mein error aaya.");
      }
    } catch {
      setError("Server se connect nahi ho pa raha. Dobara try karein.");
    } finally {
      setLoading(false);
    }
  };

  // Step 2: Verify OTP
  const handleVerifyOtp = async () => {
    setError("");
    if (!otp.trim()) {
      setError("OTP daalna zaroori hai.");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch(`${API}/verify-login-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ identifier: identifier.trim(), otp: otp.trim() }),
      });
      const data = await res.json();

      if (data.success) {
        localStorage.setItem("token", data.token);
        localStorage.setItem("user", JSON.stringify(data.user));
        onSuccess(); // navigate to /home
      } else {
        setError(data.message || "OTP galat hai ya expire ho gaya.");
      }
    } catch {
      setError("OTP verify nahi ho paya. Dobara try karein.");
    } finally {
      setLoading(false);
    }
  };

  // Resend OTP (go back to step 1)
  const handleResend = () => {
    setOtp("");
    setError("");
    setStep("enter_email");
  };

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        style={{
          position: "fixed",
          inset: 0,
          background: "rgba(80,0,120,0.35)",
          backdropFilter: "blur(4px)",
          zIndex: 999,
        }}
      />

      {/* Modal Box */}
      <div
        style={{
          position: "fixed",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          background: "#fff",
          borderRadius: "16px",
          padding: "32px 28px",
          width: "90%",
          maxWidth: "380px",
          zIndex: 1000,
          boxShadow: "0 20px 60px rgba(148,0,211,0.25)",
          boxSizing: "border-box",
        }}
      >
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
          <h2
            style={{
              fontSize: "20px",
              fontWeight: 700,
              background: "linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233))",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text",
            }}
          >
            {step === "enter_email" ? "OTP se Login karein 🔐" : "OTP Enter karein ✉️"}
          </h2>
          <span
            onClick={onClose}
            style={{ cursor: "pointer", fontSize: "20px", color: "#aaa", lineHeight: 1 }}
          >
            ✕
          </span>
        </div>

        {/* Error */}
        {error && (
          <div
            style={{
              color: "#991b1b",
              marginBottom: "12px",
              fontSize: "13px",
              background: "#fee2e2",
              padding: "10px 12px",
              borderRadius: "8px",
              border: "1px solid #fca5a5",
            }}
          >
            {error}
          </div>
        )}

        {/* ── STEP 1: Enter Email/Phone ── */}
        {step === "enter_email" && (
          <>
            <p style={{ fontSize: "13px", color: "#777", marginBottom: "16px" }}>
              Apna registered Email ya Phone number daalo. Agar account nahi hai to pehle{" "}
              <a href="/register" style={{ color: "rgb(148,0,211)", fontWeight: 600, textDecoration: "none" }}>
                Register
              </a>{" "}
              karo.
            </p>
            <input
              style={inputStyle(focusId)}
              placeholder="Email ya Phone"
              value={identifier}
              onChange={(e) => setIdentifier(e.target.value)}
              onFocus={() => setFocusId(true)}
              onBlur={() => setFocusId(false)}
              onKeyDown={(e) => e.key === "Enter" && handleSendOtp()}
              autoComplete="username"
            />
            <button
              onClick={handleSendOtp}
              disabled={loading}
              style={{
                width: "100%",
                height: "48px",
                background: "linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233))",
                color: "white",
                border: "none",
                borderRadius: "8px",
                cursor: loading ? "not-allowed" : "pointer",
                fontSize: "15px",
                fontWeight: 600,
                opacity: loading ? 0.7 : 1,
                boxShadow: "0 4px 18px rgba(148,0,211,0.3)",
                transition: "opacity 0.2s",
              }}
            >
              {loading ? "Bhej raha hai..." : "Send OTP"}
            </button>
          </>
        )}

        {/* ── STEP 2: Enter OTP ── */}
        {step === "enter_otp" && (
          <>
            <p style={{ fontSize: "13px", color: "#777", marginBottom: "16px" }}>
              OTP bheja gaya hai{" "}
              <strong style={{ color: "rgb(148,0,211)" }}>{identifier}</strong> par.
            </p>
            <input
              style={inputStyle(focusOtp)}
              placeholder="6-digit OTP"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              onFocus={() => setFocusOtp(true)}
              onBlur={() => setFocusOtp(false)}
              onKeyDown={(e) => e.key === "Enter" && handleVerifyOtp()}
              maxLength={6}
              inputMode="numeric"
              autoComplete="one-time-code"
            />
            <button
              onClick={handleVerifyOtp}
              disabled={loading}
              style={{
                width: "100%",
                height: "48px",
                background: "linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233))",
                color: "white",
                border: "none",
                borderRadius: "8px",
                cursor: loading ? "not-allowed" : "pointer",
                fontSize: "15px",
                fontWeight: 600,
                opacity: loading ? 0.7 : 1,
                boxShadow: "0 4px 18px rgba(148,0,211,0.3)",
                transition: "opacity 0.2s",
                marginBottom: "12px",
              }}
            >
              {loading ? "Verify ho raha hai..." : "Verify & Login"}
            </button>

            {/* Resend OTP */}
            <p
              onClick={handleResend}
              style={{
                textAlign: "center",
                fontSize: "13px",
                color: "rgb(148,0,211)",
                cursor: "pointer",
                fontWeight: 500,
              }}
            >
              OTP nahi aaya? Resend karein
            </p>
          </>
        )}
      </div>
    </>
  );
}

// ─── Main Login Component ─────────────────────────────────────────────────────
export default function Login() {
  const navigate = useNavigate();

  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);
  const [showForgot, setShowForgot] = useState(false);
  const [showOtpPopup, setShowOtpPopup] = useState(false); // ← NEW

  const handleLogin = async () => {
    setError("");
    if (!identifier.trim()) { setError("Email ya Phone daalna zaroori hai."); return; }
    if (!password.trim()) { setError("Password daalna zaroori hai."); return; }

    setLoading(true);
    try {
      const res = await fetch(`${API}/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ identifier: identifier.trim(), password }),
      });
      const data = await res.json();

      if (data.success) {
        localStorage.setItem("token", data.token);
        localStorage.setItem("user", JSON.stringify(data.user));
        navigate("/home");
      } else {
        setError(data.message);
      }
    } catch {
      setError("Server se connect nahi ho pa raha. Dobara try karein.");
    } finally {
      setLoading(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter") handleLogin();
  };

  return (
    <div className="main-container">

      {/* LEFT PANEL */}
      <div className="login-left">
        <h2 className="logo">TheZuro</h2>
        <p className="tagline">Join India's fastest growing shopping platform 🚀</p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right">
        <div className="form-container">

          <h1 className="brand-title">TheZuro</h1>
          <h2 className="welcome-text">Welcome Back 👋</h2>

          {error && <div className="error">{error}</div>}

          <input
            style={inputStyle(focusId)}
            placeholder="Email ya Phone"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            onFocus={() => setFocusId(true)}
            onBlur={() => setFocusId(false)}
            onKeyDown={onKeyDown}
            autoComplete="username"
          />

          <div className="password-box">
            <input
              style={inputStyle(focusPw)}
              type={showPw ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              onFocus={() => setFocusPw(true)}
              onBlur={() => setFocusPw(false)}
              onKeyDown={onKeyDown}
              autoComplete="current-password"
            />
            <span onClick={() => setShowPw(!showPw)}>
              {showPw ? "🙈" : "👁"}
            </span>
          </div>

          <div className="forgot">
            <span onClick={() => setShowForgot(true)}>Forgot Password?</span>
          </div>

          {/* Two buttons side by side */}
          <div style={{ display: "flex", gap: "10px", marginBottom: "16px" }}>
            <button onClick={handleLogin} disabled={loading}>
              {loading ? "Logging in..." : "Login"}
            </button>
            <button
              onClick={() => setShowOtpPopup(true)} // ← Opens OTP popup
              style={{ background: "transparent", border: "1.5px solid rgb(148,0,211)", color: "rgb(148,0,211)", boxShadow: "none" }}
            >
              OTP Login
            </button>
          </div>

          <p style={{ textAlign: "center", marginTop: 16, fontSize: 14, color: "#888" }}>
            Account nahi hai?{" "}
            <span
              onClick={() => navigate("/register")}
              style={{ color: "rgb(148,0,211)", fontWeight: 600, cursor: "pointer" }}
            >
              Register karein
            </span>
          </p>

        </div>
      </div>

      {/* Forgot Password Popup */}
      {showForgot && (
        <ForgotPasswordPopup onClose={() => setShowForgot(false)} />
      )}

      {/* OTP Login Popup */}
      {showOtpPopup && (
        <OtpLoginPopup
          onClose={() => setShowOtpPopup(false)}
          onSuccess={() => navigate("/home")}
        />
      )}

      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'DM Sans', Arial, sans-serif; }
        html, body { width: 100%; height: 100%; overflow-x: hidden; }
        .main-container { display: flex; flex-direction: column; min-height: 100dvh; }
        .login-left { display: none; }
        .login-right { width: 100%; display: flex; align-items: center; justify-content: center; padding: 40px 20px; }
        .form-container { width: 100%; max-width: 380px; text-align: center; margin-top: 40px; }
        .brand-title { font-size: 28px; font-weight: 700; background: linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; margin-bottom: 6px; }
        .welcome-text { font-size: 20px; font-weight: 600; background: linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; margin-bottom: 24px; }
        .error { color: #991b1b; margin-bottom: 10px; font-size: 13px; text-align: left; background: #fee2e2; padding: 10px 12px; border-radius: 8px; border: 1px solid #fca5a5; }
        .password-box { position: relative; }
        .password-box span { position: absolute; right: 12px; top: 14px; cursor: pointer; font-size: 16px; }
        .forgot { text-align: right; margin-top: -6px; margin-bottom: 18px; }
        .forgot span { font-size: 13px; font-weight: 500; background: linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; cursor: pointer; }
        button { width: 100%; height: 48px; background: linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233)); color: white; border: none; border-radius: 8px; cursor: pointer; font-size: 15px; font-weight: 600; box-shadow: 0 4px 18px rgba(148,0,211,0.3); transition: opacity 0.2s; }
        button:disabled { opacity: 0.7; cursor: not-allowed; }
        button:hover:not(:disabled) { opacity: 0.9; }
        @media (min-width: 768px) {
          .main-container { flex-direction: row; }
          .login-left { display: flex; flex: 1; background: linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233)); color: white; padding: 60px; flex-direction: column; justify-content: center; }
          .logo { font-size: 32px; font-weight: 700; margin-bottom: 12px; }
          .tagline { font-size: 16px; opacity: 0.85; }
          .login-right { max-width: 500px; }
        }
      `}</style>
    </div>
  );
}
